CREATE OR REPLACE FUNCTION ppo.materialise_legacy_estimate(e ppo.estimates)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
DECLARE group_id uuid:=gen_random_uuid();
BEGIN
 INSERT INTO ppo.estimating_workspaces(id,workspace_id,company_id,opportunity_id,owner_id,selected_option_id,legacy_estimate_id,created_by,updated_by)
  VALUES(group_id,e.workspace_id,e.company_id,e.opportunity_id,e.owner_id,e.option_id,e.id,e.created_by,e.created_by);
 INSERT INTO ppo.estimating_options(id,workspace_id,company_id,estimating_workspace_id,ordinal,label,current_revision_id,workspace_version,created_by,updated_by)
  VALUES(e.option_id,e.workspace_id,e.company_id,group_id,1,'A',e.estimation_revision_id,1,e.created_by,e.created_by);
 INSERT INTO ppo.estimation_revisions(id,workspace_id,company_id,estimating_workspace_id,option_id,version,kind,legacy_estimate_id,legacy_source_created_at,site_id,scope_readiness,reason,created_by)
  VALUES(e.estimation_revision_id,e.workspace_id,e.company_id,group_id,e.option_id,1,'LegacyManual',e.id,e.created_at,e.site_id,'NotRecorded','E1 identity formalisation only; no E2 questionnaire recorded',e.created_by);
END $function$

CREATE OR REPLACE FUNCTION ppo.acceptance_commissioning_changed()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE s record; activity uuid; changed_cause text;
BEGIN
 FOR s IN SELECT DISTINCT st.* FROM ppo.acceptance_stages st JOIN ppo.acceptance_stage_units l ON l.workspace_id=st.workspace_id AND l.stage_id=st.id AND l.revision=st.revision AND l.disposition='Included'
 JOIN ppo.acceptance_requirements r ON r.workspace_id=l.workspace_id AND r.unit_id=l.unit_id JOIN ppo.acceptance_sources src ON src.workspace_id=r.workspace_id AND src.id=r.source_id
 WHERE src.workspace_id=NEW.workspace_id AND src.commissioning_id=NEW.id AND EXISTS(SELECT 1 FROM ppo.acceptance_decisions d WHERE d.workspace_id=st.workspace_id AND d.stage_id=st.id AND d.kind='Technical') LOOP
  UPDATE ppo.acceptance_stages SET reassessment=true,version=version+1,updated_at=clock_timestamp(),updated_by=NEW.updated_by WHERE id=s.id;
  changed_cause:='en08:'||NEW.id||':'||NEW.version;
  IF NOT EXISTS(SELECT 1 FROM ppo.acceptance_followups WHERE workspace_id=s.workspace_id AND stage_id=s.id AND acceptance_followups.cause=changed_cause) THEN
   activity:=gen_random_uuid();
   INSERT INTO ppo.activities(id,workspace_id,company_id,site_id,kind,owner_id,summary,due_at,due_needed,access_class,created_by,updated_by)
   SELECT activity,s.workspace_id,s.company_id,p.site_id,'TechnicalFollowUp',s.owner_id,'Reassess changed technical evidence for acceptance stage',NULL,true,'Internal',NEW.updated_by,NEW.updated_by FROM ppo.projects p WHERE p.workspace_id=s.workspace_id AND p.id=s.project_id;
   INSERT INTO ppo.activity_links(workspace_id,company_id,activity_id,object_type,object_id) VALUES(s.workspace_id,s.company_id,activity,'Project',s.project_id);
   INSERT INTO ppo.acceptance_followups VALUES(s.workspace_id,s.project_id,s.id,changed_cause,activity);
  END IF;
 END LOOP;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION ppo.pack_owned_follow_up()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE p record; task uuid;
BEGIN
 IF NEW.kind NOT IN ('ReviewRequired','Withdrawn','Returned') THEN RETURN NEW; END IF;
 SELECT pk.*,w.service_owner_id,a.display_number AS appointment_number,a.start_at,a.site_timezone INTO p FROM ppo.pack_issues i JOIN ppo.packs pk ON pk.id=i.pack_id JOIN ppo.appointments a ON a.id=pk.appointment_id JOIN ppo.work_orders w ON w.id=a.work_order_id WHERE i.id=NEW.issue_id;
 task:=gen_random_uuid();
 IF NEW.kind='Returned' THEN
  INSERT INTO ppo.activities(id,workspace_id,company_id,site_id,created_by,updated_by,kind,owner_id,summary,due_at,due_needed,access_class)
  VALUES(task,NEW.workspace_id,p.company_id,p.site_id,NEW.actor_id,NEW.actor_id,'CustomerContact',p.service_owner_id,p.display_number||' · returned by the crew: appointment '||p.appointment_number||' is at risk. Dispatch stays held until the whole crew acknowledges a revised issue, or the preparer answers the return. The booking is unchanged and no message has been sent.',
   least(((p.start_at AT TIME ZONE p.site_timezone)::date+time '09:00') AT TIME ZONE p.site_timezone,p.start_at-interval '2 hours'),false,'RestrictedService');
 ELSE
  INSERT INTO ppo.activities(id,workspace_id,company_id,site_id,created_by,updated_by,kind,owner_id,summary,due_at,due_needed,access_class)
  VALUES(task,NEW.workspace_id,p.company_id,p.site_id,NEW.actor_id,NEW.actor_id,'CustomerContact',p.service_owner_id,p.display_number||' · '||NEW.kind||': urgently review crew/customer contact and record the outcome; no message has been sent.',NULL,true,'RestrictedService');
 END IF;
 INSERT INTO ppo.activity_links(workspace_id,company_id,activity_id,object_type,object_id) VALUES(NEW.workspace_id,p.company_id,task,'Site',p.site_id);
 INSERT INTO ppo.pack_follow_ups VALUES(NEW.workspace_id,NEW.id,task);
 RETURN NEW;
END $function$
